3	import java.sql.PreparedStatement;
4	import java.sql.Statement;
5	import java.time.LocalDateTime;
6	import java.util.List;
7	import java.util.Optional;
8	
9	import org.springframework.jdbc.core.JdbcTemplate;
10	import org.springframework.jdbc.core.RowMapper;
11	import org.springframework.jdbc.support.GeneratedKeyHolder;
12	import org.springframework.jdbc.support.KeyHolder;
13	import org.springframework.stereotype.Repository;
14	
15	import com.example.starter.calibration.model.Measurement;
16	import com.example.starter.calibration.model.MeasurementStatus;
17	
18	/**
19	 * 测量记录持久化。measurement_key 全局唯一作为幂等键；状态流转由放行事务在行锁内完成。
20	 */
21	@Repository
22	public class MeasurementRepository {
23	
24	    private static final RowMapper<Measurement> MAPPER = (rs, rowNum) -> new Measurement(
25	            rs.getLong("id"),
26	            rs.getString("measurement_key"),
27	            rs.getString("instrument_id"),
28	            JdbcTimes.fromDb(rs.getObject("measured_at", LocalDateTime.class)),
29	            rs.getBigDecimal("raw_reading"),
30	            rs.getBigDecimal("lower_limit"),
31	            rs.getBigDecimal("upper_limit"),
32	            rs.getString("submitted_by"),
33	            rs.getLong("certificate_id"),
34	            rs.getBigDecimal("computed_value"),
35	            rs.getBoolean("passed"),
36	            MeasurementStatus.valueOf(rs.getString("status")),
37	            JdbcTimes.fromDb(rs.getObject("created_at", LocalDateTime.class)));
38	
39	    private final JdbcTemplate jdbc;
40	
41	    public MeasurementRepository(JdbcTemplate jdbc) {
42	        this.jdbc = jdbc;
43	    }
44	
45	    /**
46	     * 插入测量记录并返回生成的 ID；measurement_key 冲突时抛出 DuplicateKeyException。
47	     */
48	    public long insert(Measurement measurement) {
49	        KeyHolder keyHolder = new GeneratedKeyHolder();
50	        jdbc.update(con -> {
51	            PreparedStatement ps = con.prepareStatement(
52	                    "INSERT INTO measurement "
53	                            + "(measurement_key, instrument_id, measured_at, raw_reading, lower_limit, upper_limit, "
54	                            + "submitted_by, certificate_id, computed_value, passed, status, created_at) "
55	                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
56	                    Statement.RETURN_GENERATED_KEYS);
57	            ps.setString(1, measurement.measurementKey());
58	            ps.setString(2, measurement.instrumentId());
59	            ps.setObject(3, JdbcTimes.toDb(measurement.measuredAt()));
60	            ps.setBigDecimal(4, measurement.rawReading());
61	            ps.setBigDecimal(5, measurement.lowerLimit());
62	            ps.setBigDecimal(6, measurement.upperLimit());
63	            ps.setString(7, measurement.submittedBy());
64	            ps.setLong(8, measurement.certificateId());
65	            ps.setBigDecimal(9, measurement.computedValue());
66	            ps.setBoolean(10, measurement.passed());
67	            ps.setString(11, measurement.status().name());
68	            ps.setObject(12, JdbcTimes.toDb(measurement.createdAt()));
69	            return ps;
70	        }, keyHolder);
71	        return keyHolder.getKey().longValue();
72	    }
73	
74	    /**
75	     * 按测量键查询（不加锁）。
