15	/**
16	 * 校准证书服务：创建（区间不重叠，并发安全）、撤销、查询。
17	 */
18	@Service
19	public class CertificateService {
20	
21	    private final CertificateRepository certificates;
22	
23	    public CertificateService(CertificateRepository certificates) {
24	        this.certificates = certificates;
25	    }
26	
27	    /**
28	     * 创建证书。同一仪器未撤销证书区间不得重叠（相邻合法）；
29	     * 通过仪器级行锁串行化，并发创建重叠证书时最多一张成功。
30	     */
31	    @Transactional
32	    public CertificateResponse create(CreateCertificateRequest request) {
33	        String instrumentId = Inputs.requireText(request.instrumentId(), "instrumentId");
34	        Instant validFrom = Inputs.requireInstant(request.validFrom(), "validFrom");
35	        Instant validTo = Inputs.requireInstant(request.validTo(), "validTo");
36	        BigDecimal a = Inputs.requireDecimal(request.a(), "a");
37	        BigDecimal b = Inputs.requireDecimal(request.b(), "b");
38	        if (!validFrom.isBefore(validTo)) {
39	            throw ApiException.badRequest("validFrom 必须早于 validTo");
40	        }
41	
42	        certificates.lockInstrument(instrumentId);
43	        if (certificates.countActiveOverlap(instrumentId, validFrom, validTo) > 0) {
44	            throw ApiException.conflict("CERTIFICATE_OVERLAP", "同一仪器存在区间重叠的未撤销证书");
45	        }
46	        long id = certificates.insert(instrumentId, validFrom, validTo, a, b, Instant.now());
47	        return DtoMapper.toResponse(certificates.findById(id).orElseThrow());
48	    }
49	
50	    /**
51	     * 撤销证书。不存在返回 404；重复撤销返回 409。
52	     * 与批量放行并发时按事务提交顺序生效：撤销先提交则放行整批拒绝。
53	     */
54	    @Transactional
55	    public CertificateResponse revoke(long id) {
56	        Certificate cert = certificates.findByIdForUpdate(id)
57	                .orElseThrow(() -> ApiException.notFound("证书不存在: " + id));
58	        if (cert.revoked()) {
59	            throw ApiException.conflict("ALREADY_REVOKED", "证书已撤销: " + id);
60	        }
61	        certificates.markRevoked(id, Instant.now());
62	        return DtoMapper.toResponse(certificates.findById(id).orElseThrow());
63	    }
64	
65	    /**
66	     * 按 ID 查询证书，不存在返回 404。
67	     */
68	    @Transactional(readOnly = true)
69	    public CertificateResponse get(long id) {
70	        return DtoMapper.toResponse(certificates.findById(id)
71	                .orElseThrow(() -> ApiException.notFound("证书不存在: " + id)));
72	    }
73	}
